def solution(input_str):
    lines = input_str.strip().split('\n')
    k = int(lines[0])
    n = 2**k
    a = list(map(int, lines[1].split()))

    # Solution function to check if valid permutations exist
    def backtrack(idx, p, q, used_p, used_q, result):
        if idx == n:
            result.append((p[:], q[:]))
            return True

        for val in range(n):
            if used_p[val]:
                continue

            if val is None:
                # Spanning tree search - try to fill q[idx] based on p[idx]
                for q_val in range(n):
                    if q_val is None:
                        continue
                    xor_val = q_val ^ a[idx]
                    if not used_p[xor_val]:
                        p[idx] = xor_val
                        q[idx] = q_val
                        result.append((p, [q_val]) + q)
                        return False
                return False

            for q_val in range(n):
                if used_p[q_val ^ a[idx]]:
                    continue
                p[idx] = q_val ^ a[idx]
                q[idx] = q_val
                if p[idx] < n and not used_p[p[idx]]:
                    used_p.add(p[idx])
                    used_q.add(q[idx])
                    if backtrack(idx + 1, p, q, used_p, used_q, result):
                        return True
                    used_p.remove(p[idx])
                    used_q.remove(q[idx])

        return False

    # Simple direct solution check
    for p_attempt in [list(range(n))]:
        q_candidates = [p_attempt[idx] ^ a[idx] for idx in range(n)]
        if sorted(q_candidates) == list(range(n)):
            return f"Shi\n{' '.join(map(str, p_attempt))}\n{' '.join(map(str, q_candidates))}\n"

    # More comprehensive backtracking
    result = []
    p = [0] * n
    q = [0] * n

    if backtrack(0, p, q, set(), set(), result):
        p_final = result[0][0] if result else None
        q_final = result[0][1] if result else None

        if p_final and q_final:
            # Verify solution
            if all(sorted(p_final) == sorted(range(n))) and all(sorted(q_final) == sorted(range(n))):
                return f"Shi\n{' '.join(map(str, p_final))}\n{' '.join(map(str, q_final))}\n"

    return "Fou\n"

