imports
def fact_mod(n, mod):
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod
    return result

def inverse(n, mod):
    return pow(n, mod - 2, mod)

def combinations(n, r, mod):
    if r < 0 or r > n:
        return 0
    num = fact_mod(n, mod)
    den = (fact_mod(r, mod) * fact_mod(n - r, mod)) % mod
    return (num * inverse(den, mod)) % mod

