            balance = 0
            for x in seq:
                balance += x
                if balance < 0:
                    return False
            return balance == 0

        def construct_order(cards):
            # Try sorting by |front| ascending first
            order1 = sorted(cards, key=lambda c: (abs(c[0]), c[1], c[0], c[1]))
            if is_balanced([c[0] for c in order1]) and is_balanced([c[1] for c in order1]):
                return order1

            # Try sorting by front value descending
            order2 = sorted(cards, key=lambda c: (-c[0], -abs(c[1])))
            if is_balanced([c[0] for c in order2]) and is_balanced([c[1] for c in order2]):
                return order2

            # Randomized attempts for harder cases
            import random
            random.seed(42)
            for _ in range(50000):
                shuffled = cards[:]
                random.shuffle(shuffled)
                front = [c[0] for c in shuffled]
                back = [c[1] for c in shuffled]
                if is_balanced(front) and is_balanced(back):
                    return shuffled

            # Another heuristic: process large positives first, then negatives
            odds = [(i, c) for i, c in enumerate(cards) if c[0] > 0]
            evens = [(i, c) for i, c in enumerate(cards) if c[0] < 0]

            odds.sort(key=lambda x: x[1][0], reverse=True)
            odds.sort(key=lambda x: -x[1][1])
            evens.sort(key=lambda x: x[1][1], reverse=True)

            ordered = [c for _, c in odds] + [c for _, c in evens]
            if is_balanced([c[0] for c in ordered]) and is_balanced([c[1] for c in ordered]):
                return ordered

            return None

        result = construct_order(cards)
