def dinic_max_flow(n_nodes, source, sink, cap_matrix):
    """Dinic's algorithm for max flow"""
    # Extract all edges from capacity matrix
    edges = []
    for u in range(n_nodes):
        for v in range(n_nodes):
            if u != v or cap_matrix[u][v] > 0:
                edges.append((u, v, cap_matrix[u][v]))

    # Build adjacency list with residual capacities
    graph = [[] for _ in range(n_nodes)]
    edge_list = []

    for i, (u, v, cap) in enumerate(edges):
        if cap == float('inf'):
            capacity = float('inf')
        else:
            capacity = cap
        edge_list.append((u, v, capacity, len(graph[v]), len(graph[u]) - 1))
        graph[u].append(len(edge_list) - 1)
        graph[v].append(len(edge_list))

    level = [0] * n_nodes
    ptr = [0] * n_nodes

    def bfs():
        for i in range(n_nodes):
            level[i] = -1
        level[source] = 0
        queue = deque([source])
        while queue:
            u = queue.popleft()
            for e_idx in graph[u]:
                u_orig, v_orig, capacity, _, _ = edge_list[e_idx]
                if capacity > 0 and level[v_orig] == -1:
                    level[v_orig] = level[u] + 1
                    queue.append(v_orig)
        return level[sink] != -1

    def dfs(u, pushed):
        if pushed == 0 or u == sink:
            return pushed
        for i in range(ptr[u], len(graph[u])):
