def solution(n_input):
    """
    Solves the magic number problem: minimum subtractions to reduce n to 0,
    where each step subtracts a digit present in the current number.
    """
    import sys

    n = 0
    if n_input:
        try:
            n = int(n_input.strip())
        except (ValueError, AttributeError):
            n = 0

    if n == 0:
        return '0\n'

    # For extremely large numbers, use greedy approach
    if n > 10**13:
        count = 0
        while n > 0:
            if n == 0:
                break
            largest = max(int(d) for d in str(n))
            n -= largest
            count += 1
        return str(count) + '\n'

    # BFS with memoization for reasonable-sized inputs
    from collections import deque

    memo = {}
    visited = set()

    queue = deque([(n, 0)])
    visited.add(n)

    while queue:
        current, steps = queue.popleft()

        if current == 0:
            return str(steps) + '\n'

        if current in memo:
            continue

        s = str(current)
        digits = sorted(set(int(d) for d in s))

        for d in digits:
            new_val = current - d
            if 0 <= new_val not in visited:
                visited.add(new_val)
                queue.append((new_val, steps + 1))

    # Fallback: should never reach here
    return '0\n'


