                prev_start, prev_size = placements[group_idx-1]
                if s - prev_start - prev_size < 1:  # need at least 1 gap
                    continue

            placements.append((s, group_size))
            if s + group_size <= n:
                backtrack(s + group_size, group_idx + 1, placements)
